/**
 * A single invoice with the line items it is built from: their subtotal, the percentage and flat
 * amount discount and what they take off, and the sales tax percentage, the taxable base it is charged on (the taxable
 * lines after the discount, leaving out tax-free ones) and what it adds, and the levy (a second tax)
 * percentage and what it adds on that same base; its amount is the subtotal less the discount plus
 * the tax plus the levy.
 */
export interface InvoiceDetail extends Invoice {
  /** The total before tax: the amount less the sales tax and levy. */
  totalExTax: number;
  subtotal: number;
  discountPct: number;
  /** A flat amount taken off the subtotal after the percentage; zero when there is none. */
  discountAmount: number;
  /** What the percentage and flat amount take off together. */
  discount: number;
  taxPct: number;
  taxableBase: number;
  tax: number;
  levyPct: number;
  levy: number;
  /** Whether the prices already include the tax and levy, so they are worked back out rather than added on. */
  taxInclusive: boolean;
  /** Whether the client is tax exempt, so the invoice carries no tax or levy whatever its lines say. */
  taxExempt: boolean;
  /** The overall tax rate that ended up on the invoice: the tax and levy as a percentage of the total before tax. */
  effectiveTaxPct: number;
  /** The percentage taken off when paid early; zero when no early-payment discount is offered. */
  earlyPaymentPct: number;
  /** How many days after being issued it must be paid within to get the early-payment discount. */
  earlyPaymentDays: number;
  /** The last day to pay to get the early-payment discount; null when none is offered. */
    });
  }

  /** Sets the sales tax percentage added to a draft invoice after its discount; zero removes the tax. */
  applyTax(projectId: number, invoiceId: number, taxPct: number): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/tax`, { taxPct });
  }

  /** Sets the levy (second tax) percentage added to a draft invoice on top of its sales tax; zero removes the levy. */
  applyLevy(projectId: number, invoiceId: number, levyPct: number): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/levy`, { levyPct });
  }

  /** Sets the early-payment discount offered on a draft invoice; zero for either removes the offer. */
  applyEarlyPayment(projectId: number, invoiceId: number, earlyPaymentPct: number, earlyPaymentDays: number): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/early-payment`, {
import { CurrencyPipe, DecimalPipe } from '@angular/common';
import { Component, Injector, afterNextRender, computed, effect, inject, input, signal } from '@angular/core';
import { rxResource, toSignal } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { Observable } from 'rxjs';
import { Notes } from '../notes/notes';
import { InvoicePayments } from '../payments/invoice-payments';
import { InvoiceDetail, InvoiceService, LineItem } from './invoice.service';

const TWO_DECIMALS = /^\d+(\.\d{1,2})?$/;
// A unit price may be a fraction of a cent; each line is rounded to the cent on its own.
const FOUR_DECIMALS = /^\d+(\.\d{1,4})?$/;

// A single invoice: the client's tax number when they are tax registered, the things it charges for (description, how many and of what, price each), each line's
// amount, their subtotal, any percentage or flat amount discount (one or the other, taken off before tax), the taxable amount (leaving out tax-free lines), any
// sales tax added on it after the discount, any levy (a second tax) added on the same base, the effective tax rate
// (the tax and levy as a percentage of the total before tax), the total before tax, and the final total including both taxes (also shown as the total after tax).
// For a client whose prices already include tax, the tax and levy are instead shown as worked back out of the price; the total is unchanged.
// When an early-payment discount is offered, it also shows the reduced amount to pay if settled within the set number of days.
// Lines, the discount, the tax rate, the levy rate and the early-payment discount can be changed while it is a draft.
@Component({
